    final origin = _origin;
    if (origin == null || !packageLinkAdmitted(url, origin)) {
      return false;
    }
    final bytes = await _fetch(url);
    if (bytes == null) {
      return false;
    }
    try {
      await _store.put(key, base64Encode(bytes));
      return true;
    } on IOException {
      return false;
    }
  }

  /// Unpacks the archive kept under [key] into entries `<key>/<path>`, answering the member
  /// paths, sorted, or `null` when the archive is refused -- and then nothing under `<key>/`
  /// remains.
