        for (final member in _admittedMembers(base64Decode(kept), _limits)) {
          await _store.put('$key$_separator${member.path}', base64Encode(member.read()));
          paths.add(member.path);
        }
      } on _ArchiveRefused {
        await _deleteUnder(key);
        return null;
      }
      return paths..sort();
    } on IOException {
      return null;
    }
  }

  /// The SHA-256 of the bytes kept under [key], as 64 lowercase hex digits, or `null`.
  Future<String?> sha256(String key) async {
    try {
      final kept = await _store.get(key);
      return kept == null ? null : sha256Hex(base64Decode(kept));
    } on IOException {
      return null;
    }
  }

  /// Moves every file under `<source>/` to the same path under `<target>/`, answering whether
  /// all moved; what `<target>/` held before is removed first.
  Future<bool> move(String source, String target) async {
    try {
      await _deleteUnder(target);
      final prefix = '$source$_separator';
      for (final key in await _store.keys()) {
        if (!key.startsWith(prefix)) {
          continue;
        }
        final kept = await _store.get(key);
        if (kept != null) {
          await _store.put('$target$_separator${key.substring(prefix.length)}', kept);
        }
        await _store.remove(key);
      }
      return true;
    } on IOException {
      return false;
    }
  }

  /// Removes the entry [prefix] and every file under `<prefix>/`, answering whether all were removed.
  Future<bool> delete(String prefix) async {
    try {
      await _store.remove(prefix);
      await _deleteUnder(prefix);
      return true;
    } on IOException {
      return false;
    }
  }

  Future<void> _deleteUnder(String prefix) async {
    final under = '$prefix$_separator';
    for (final key in await _store.keys()) {
      if (key.startsWith(under)) {
        await _store.remove(key);
      }
    }
  }
}

/// The SHA-256 of [bytes], as 64 lowercase hex digits.
String sha256Hex(List<int> bytes) => crypto.sha256.convert(bytes).toString();
